use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    requires
        true,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
        a@ == old(a@),
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == a[j],
            a@ == old(a@),
        decreases a.len() - i,
    {
        // Safe because i < a.len() by loop guard
        let x: T = a[i];
        result.push(x);
        i = i + 1;
    }

    result
}

} // verus!

